draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // Draw a watch
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw hour and minute hands
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 40 * Math.sin(2 * Math.PI * (t + 1759/60)), H/2 - 40 * Math.cos(2 * Math.PI * (t + 1759/60)));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 30 * Math.sin(2 * Math.PI * (t + 1759/600)), H/2 - 30 * Math.cos(2 * Math.PI * (t + 1759/600)));
  ctx.stroke();

  // Add a stick figure admiring the watch
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 40);
  ctx.lineTo(W/2 - 100, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 20);
  ctx.lineTo(W/2 - 80, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 20);
  ctx.lineTo(W/2 - 120, H/2);
  ctx.stroke();

  ctx.restore();
}
